/*
 * fst_fixture.c - write the small FST fixture read by tools/test_fst_reader.py.
 *
 * This is test data, not a simulator. Build it against the same libfst source
 * as tools/fst_read.c and run it in the directory where simple.fst should be
 * written. The committed fixture was generated by:
 *
 *   cc -O2 -I "$LIBFST/src" -o fst_fixture tools/fst_fixture.c \
 *      "$LIBFST/src/fstapi.c" "$LIBFST/src/lz4.c" "$LIBFST/src/fastlz.c" \
 *      -lz -lbz2
 *   ./fst_fixture simple.fst
 */

#include "fstapi.h"

int main(int argc, char **argv)
{
    fstWriterContext *writer;
    fstHandle a, b;

    if (argc != 2) return 2;
    writer = fstWriterCreate(argv[1], 1);
    if (writer == NULL) return 2;
    fstWriterSetTimescale(writer, -9);
    fstWriterSetScope(writer, FST_ST_VCD_MODULE, "top", NULL);
    a = fstWriterCreateVar(writer, FST_VT_VCD_WIRE, FST_VD_OUTPUT, 8, "a", 0);
    b = fstWriterCreateVar(writer, FST_VT_VCD_REG, FST_VD_OUTPUT, 1, "b", 0);
    fstWriterEmitTimeChange(writer, 0);
    fstWriterEmitValueChange(writer, a, "00000101");
    fstWriterEmitValueChange(writer, b, "0");
    fstWriterEmitTimeChange(writer, 10);
    fstWriterEmitValueChange(writer, a, "10100101");
    fstWriterEmitValueChange(writer, b, "1");
    fstWriterSetUpscope(writer);
    fstWriterClose(writer);
    return 0;
}
